class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        if amount == 0:
            return 0

        q = deque([0])
        seen = [False] * (amount + 1)
        seen[0] = True
        res = 0

        while q:
            res += 1
            for _ in range(len(q)):
                cur = q.popleft()
                for coin in coins:
                    nxt = cur + coin
                    if nxt == amount:
                        return res
                    if nxt > amount or seen[nxt]:
                        continue
                    seen[nxt] = True
                    q.append(nxt)

        return -1

var coinChange = function(coins, amount) {
    if (amount === 0) {
        return 0;
    }

    const q = [0];
    const seen = new Array(amount + 1).fill(false);
    seen[0] = true;
    let res = 0;

    while (q.length > 0) {
        res++;
        const levelSize = q.length;
        for (let i = 0; i < levelSize; i++) {
            const cur = q.shift();
            for (let coin of coins) {
                const nxt = cur + coin;
                if (nxt === amount) {
                    return res;
                }
                if (nxt > amount || seen[nxt]) {
                    continue;
                }
                seen[nxt] = true;
                q.push(nxt);
            }
        }
    }

    return -1;
};

func coinChange(coins []int, amount int) int {
    if amount == 0 {
        return 0
    }

    q := []int{0}
    seen := make([]bool, amount + 1)
    seen[0] = true
    res := 0

    for len(q) > 0 {
        res++
        levelSize := len(q)
        for i := 0; i < levelSize; i++ {
            cur := q[0]
            q = q[1:]
            for _, coin := range coins {
                nxt := cur + coin
                if nxt == amount {
                    return res
                }
                if nxt > amount || seen[nxt] {
                    continue
                }
                seen[nxt] = true
